-- SELECT only. 20261128100000_mcp_claude_write 적용 뒤. 카탈로그·migration 기록·허용 행 개수만 읽는다(행 값 없음).
-- 예/아니오 항목은 모두 예, 해시는 precheck의 같은 이름 항목과 같은 값이어야 한다.
-- expect: history row present = 예
-- expect: mcp_write allow row only on calls workspace = 예
-- expect: feature check includes mcp_write = 예
-- expect: write switch column default off screen only = 예
-- expect: write tables rls owner select only = 예
-- expect: definer helpers empty path authenticated only = 예
-- expect: invoker helpers authenticated only = 예
-- expect: three public write functions invoker empty path authenticated only = 예
-- expect: existing boundary hash = 기록
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261128100000' and name='mcp_claude_write')=1 then '예' else '아니오' end as ok
union all select 'mcp_write allow row only on calls workspace',case when (select count(*) from public.app_operator_features where feature::text='mcp_write')=1 and exists(select 1 from public.app_operator_features p join public.app_operator_features c on c.workspace_id=p.workspace_id and c.feature::text='calls' where p.feature::text='mcp_write') then '예' else '아니오' end
union all select 'feature check includes mcp_write',case when (select count(*) from pg_constraint where conrelid=to_regclass('public.app_operator_features') and conname='app_operator_features_feature_check' and pg_get_constraintdef(oid) ~ '''mcp_write''' and pg_get_constraintdef(oid) ~ '''photo_content''')=1 then '예' else '아니오' end
union all select 'write switch column default off screen only',case when exists(select 1 from pg_attribute a join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=to_regclass('public.app_mcp_settings') and a.attname='write_enabled' and a.attnotnull and a.atttypid='boolean'::regtype and pg_get_expr(d.adbin,d.adrelid)='false' and has_column_privilege('authenticated',a.attrelid,a.attnum,'update') and not has_column_privilege('anon',a.attrelid,a.attnum,'update') and not has_column_privilege('service_role',a.attrelid,a.attnum,'update'))
  and not has_any_column_privilege('anon','public.app_mcp_settings','select,insert,update,references') and not has_any_column_privilege('authenticated','public.app_mcp_settings','insert') then '예' else '아니오' end
union all select 'write tables rls owner select only',case when (select count(*) from pg_class c where c.oid in (to_regclass('public.app_mcp_write_log'),to_regclass('public.app_mcp_write_before')) and c.relrowsecurity)=2
  and has_table_privilege('authenticated','public.app_mcp_write_log','select') and has_table_privilege('authenticated','public.app_mcp_write_before','select')
  and not has_table_privilege('authenticated','public.app_mcp_write_log','insert,delete,truncate,references,trigger') and not has_table_privilege('authenticated','public.app_mcp_write_before','insert,update,delete,truncate,references,trigger')
  and not has_any_column_privilege('authenticated','public.app_mcp_write_before','update')
  and (select count(*) from pg_attribute a where a.attrelid=to_regclass('public.app_mcp_write_log') and a.attnum>0 and not a.attisdropped and has_column_privilege('authenticated',a.attrelid,a.attnum,'update'))=1
  and has_column_privilege('authenticated','public.app_mcp_write_log','undone_at','update')
  and not has_table_privilege('anon','public.app_mcp_write_log','select,insert,update,delete,truncate,references,trigger') and not has_table_privilege('anon','public.app_mcp_write_before','select,insert,update,delete,truncate,references,trigger')
  and not has_table_privilege('service_role','public.app_mcp_write_log','select,insert,update,delete,truncate,references,trigger') and not has_table_privilege('service_role','public.app_mcp_write_before','select,insert,update,delete,truncate,references,trigger')
  and (select count(*) from pg_policy p where p.polrelid in (to_regclass('public.app_mcp_write_log'),to_regclass('public.app_mcp_write_before')))=3
  and not exists(select 1 from pg_policy p where p.polrelid in (to_regclass('public.app_mcp_write_log'),to_regclass('public.app_mcp_write_before')) and p.polroles<>array[to_regrole('authenticated')]::oid[]) then '예' else '아니오' end
union all select 'definer helpers empty path authenticated only',case when (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname in ('app_mcp_write_check','app_mcp_write_gate','app_mcp_write_note','app_mcp_w_diary_locked') and p.prosecdef and p.proconfig=array['search_path=""']
    and has_function_privilege('authenticated',p.oid,'execute') and not has_function_privilege('anon',p.oid,'execute') and not has_function_privilege('service_role',p.oid,'execute') and not exists(select 1 from aclexplode(p.proacl) x where x.grantee=0))=4 then '예' else '아니오' end
union all select 'invoker helpers authenticated only',case when (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname in ('app_mcp_w_text','app_mcp_w_version','app_mcp_w_day','app_mcp_w_note_blocked') and not p.prosecdef and p.proconfig=array['search_path=""']
    and has_function_privilege('authenticated',p.oid,'execute') and not has_function_privilege('anon',p.oid,'execute') and not has_function_privilege('service_role',p.oid,'execute') and not exists(select 1 from aclexplode(p.proacl) x where x.grantee=0))=4 then '예' else '아니오' end
union all select 'three public write functions invoker empty path authenticated only',case when (select count(*) from pg_proc p where p.oid in (to_regprocedure('public.app_mcp_write(text,jsonb)'),to_regprocedure('public.app_mcp_write_tools()'),to_regprocedure('public.app_mcp_write_undo(uuid)')) and not p.prosecdef and p.proconfig=array['search_path=""']
    and has_function_privilege('authenticated',p.oid,'execute') and not has_function_privilege('anon',p.oid,'execute') and not has_function_privilege('service_role',p.oid,'execute') and not exists(select 1 from aclexplode(p.proacl) x where x.grantee=0))=3 then '예' else '아니오' end
union all select 'existing boundary hash',md5(coalesce((select string_agg(p.oid::regprocedure::text||md5(pg_get_functiondef(p.oid))||coalesce(p.proacl::text,''),',' order by p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname in('public','private') and p.proname like 'app\_mcp\_%' and p.proname not in ('app_mcp_write','app_mcp_write_tools','app_mcp_write_undo','app_mcp_write_check','app_mcp_write_gate','app_mcp_write_note','app_mcp_w_diary_locked','app_mcp_w_text','app_mcp_w_version','app_mcp_w_day','app_mcp_w_note_blocked')) or p.oid in (to_regprocedure('private.app_workspace_has_feature(uuid,text)'),to_regprocedure('private.app_is_workspace_owner(uuid)'),to_regprocedure('public.app_trash_restore(text,uuid)'))),'')||coalesce((select string_agg(c.relname::text||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in (to_regclass('public.app_notes'),to_regclass('public.app_note_folders'),to_regclass('public.app_suborganizations'),to_regclass('public.app_suborganization_updates'),to_regclass('public.app_spaces'),to_regclass('public.app_business_records'),to_regclass('public.app_operator_features'),to_regclass('public.app_mcp_read_log'),to_regclass('public.app_workspace_members'))),'')||coalesce((select string_agg(p.polrelid::regclass::text||p.polname::text||p.polcmd::text||p.polpermissive::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polrelid::regclass::text,p.polname) from pg_policy p where p.polrelid in (to_regclass('public.app_notes'),to_regclass('public.app_note_folders'),to_regclass('public.app_suborganizations'),to_regclass('public.app_suborganization_updates'),to_regclass('public.app_spaces'),to_regclass('public.app_business_records'),to_regclass('public.app_operator_features'),to_regclass('public.app_mcp_settings'),to_regclass('public.app_mcp_read_log'),to_regclass('public.app_workspace_members'))),'')||coalesce((select string_agg(t.tgrelid::regclass::text||t.tgname::text||t.tgenabled::text,',' order by t.tgrelid::regclass::text,t.tgname) from pg_trigger t where not t.tgisinternal and t.tgrelid in (to_regclass('public.app_notes'),to_regclass('public.app_suborganization_updates'),to_regclass('public.app_business_records'))),''));
